window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-04ee44547ef6093f"]={"versions": [{"id": "FIG-04ee44547ef6093f", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Top-down-Methoden- und Prozessablaufdiagramm (Engineering Workflow / Phasenmodell des AUTOSAR-Entwicklungsprozesses).</li>\n<li><strong>Technischer Zweck:</strong> Darstellung des System-Engineering-Pfads von der Anforderungsanalyse über die funktionale Dekomposition bis zur Aufspaltung in disziplinspezifische HW- und SW-Entwicklungsstränge. Es veranschaulicht die organisatorische und methodische Verantwortungsaufteilung zwischen OEM und Tier-1-Zulieferer sowie die Einspeisung standardisierter AUTOSAR-Austauschbeschreibungen in die klassische AUTOSAR-Methodologie.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm gliedert den Ablauf in drei hierarchische Domänen mit spezifischen Rollen, Entitäten und Artefakten:</p>\n<ul class=\"fig-list\">\n<li><strong>Car domain (OEM):</strong></li>\n<li><em>Marketing:</em> Identifiziert Anwendungsfälle und High-Level-Fahrzeugmerkmale (<code>Car features</code>).</li>\n<li><em>System architect:</em> Transformiert Merkmale in formale Fahrzeugfunktionen (<code>Car functions</code>).</li>\n<li><strong>Electronic domain (OEM):</strong></li>\n<li><em>Functional architects:</em> Detaillieren das Funktionsdesign (<code>Function design</code> – I/O-Definition, internes Verhalten, Subfunktionen; entspricht der VFB-Ebene / Virtual Function Bus).</li>\n<li><em>Electronic architects:</em> Führen das Funktions-ECU-Mapping durch (<code>Mapping of functions on ECU</code>) und erstellen das Kommunikationsnetzwerk (<code>Definition of comm matrix</code>, z. B. CAN/LIN/FlexRay-Cluster und Signal-PDU-Layouts).</li>\n<li><em>Schnittstellen-Artefakt:</em> <code>System Constraint Description</code> (ARXML-Austauschmodell mit Restriktionen bezüglich Busbandbreite, Latenzen, Topologie und Speicherbudget).</li>\n<li><strong>Organic domain (OEM + supplier):</strong></li>\n<li><em>Kollaborative Ebene:</em> Gemeinsame Konsolidierung der Systemspezifikation (<code>ECU system spec</code>).</li>\n<li><em>HW-Pfad:</em> Spezifikation (<code>HW spec</code>), getrieben durch die <code>ECU Resource Description</code> (Hardware-Eigenschaften: Controller-Architektur, RAM/ROM/Flash-Größen, Peripherie-Ports, Timings), überführt in die HW-Entwicklung (<code>HW dvpt</code>) bis zum finalen Target (<code>Hardware</code>).</li>\n<li><em>SW-Pfad:</em> Spezifikation (<code>SW spec</code>), formalisiert als <code>Software-component Description</code> (SWC-Template: Port-Interfaces, Internal Behavior, Runnables, Events), überführt in die SW-Implementierung (<code>SW dvpt</code>) bis zum generierten/implementierten Quellcode (<code>SWC code</code>).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Prozess folgt einer strikten Kaskadierung mit paralleler Verzweigung in der Integrationsphase:</p>\n<ol class=\"fig-list\">\n<li><strong>Anforderungsdefinition (Car Domain):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>$T_0$: Erfassung der Kundenanforderungen (<code>Car features</code>).</li>\n<li>$T_1$: Formalisierung in funktionale Anforderungen (<code>Car functions</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Architektur & Allokation (Electronic Domain):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>$T_2$: VFB-konforme Schnittstellen- und Verhaltensdefinition (<code>Function design</code>).</li>\n<li>$T_3$: Synthese aus logischer Architektur und physischer Netzwerktopologie (<code>Mapping of functions on ECU</code> & <code>Definition of comm matrix</code>).</li>\n<li>$T_4$: Export der <code>System Constraint Description</code> als verbindliche Vorgabe an die Steuergeräteebene.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>ECU-Dekomposition & Implementierung (Organic Domain):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>$T_5$: Abstimmung der <code>ECU system spec</code> zwischen OEM und Tier-1.</li>\n<li>$T_6$: Verzweigung in parallele Spezifikations- und Entwicklungsstränge:</li>\n<li><strong>Hardware-Zweig:</strong> <code>HW spec</code> $\\rightarrow$ Parametrierung via <code>ECU Resource Description</code> $\\rightarrow$ Layout/Schaltungsentwicklung (<code>HW dvpt</code>) $\\rightarrow$ Fertigung/Lieferung (<code>Hardware</code>).</li>\n<li><strong>Software-Zweig:</strong> <code>SW spec</code> $\\rightarrow$ Generierung/Modellierung der <code>Software-component Description</code> $\\rightarrow$ Implementierung (<code>SW dvpt</code>) $\\rightarrow$ Kompilat/Source (<code>SWC code</code>).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Entkopplung durch VFB:</strong> Bis zum Schritt <code>Mapping of functions on ECU</code> sind Applikationsfunktionen hardware-agnostisch modelliert. Entwickler implementieren Software-Komponenten (SWCs) ausschließlich gegen den durch die <code>Software-component Description</code> definierten API-Vertrag (Port-Interfaces, RTE-Contract-Phase).</li>\n<li><strong>Basis für RTE- und BSW-Generierung:</strong></li>\n<li>Die <code>Software-component Description</code> liefert das Input-Modell für den RTE-Generator zur Erzeugung von <code>Rte_&lt;swc&gt;.h</code> und des RTE-Glue-Codes.</li>\n<li>Die <code>ECU Resource Description</code> bildet die Basis für die MCAL- und BSW-Konfiguration (System Clocks, Memory Mapping, Pin-Multiplexing, ISR-Vektoren via Tresos, DaVinci Configurator o. ä.).</li>\n<li><strong>Lieferanten-Schnittstelle:</strong> Die strikte Trennung in <code>System Constraint Description</code>, <code>ECU Resource Description</code> und <code>Software-component Description</code> verhindert proprietäre Tool-Abhängigkeiten und sichert die Wiederverwendbarkeit von SWCs über verschiedene Hardware-Plattformen und Tier-1-Lieferanten hinweg.</li>\n</ul>"}, {"id": "FIG-3b33d83ce39c7c2c", "releases": ["R3.0.7", "R3.1.5", "R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Top-down-Methoden- und Prozessablaufdiagramm (Engineering Workflow / Phasenmodell des AUTOSAR-Entwicklungsprozesses).</li>\n<li><strong>Technischer Zweck:</strong> Darstellung des System-Engineering-Pfads von der Anforderungsanalyse über die funktionale Dekomposition bis zur Aufspaltung in disziplinspezifische HW- und SW-Entwicklungsstränge. Es veranschaulicht die organisatorische und methodische Verantwortungsaufteilung zwischen OEM und Tier-1-Zulieferer sowie die Einspeisung standardisierter AUTOSAR-Austauschbeschreibungen in die klassische AUTOSAR-Methodologie.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm gliedert den Ablauf in drei hierarchische Domänen mit spezifischen Rollen, Entitäten und Artefakten:</p>\n<ul class=\"fig-list\">\n<li><strong>Car domain (OEM):</strong></li>\n<li><em>Marketing:</em> Identifiziert Anwendungsfälle und High-Level-Fahrzeugmerkmale (<code>Car features</code>).</li>\n<li><em>System architect:</em> Transformiert Merkmale in formale Fahrzeugfunktionen (<code>Car functions</code>).</li>\n<li><strong>Electronic domain (OEM):</strong></li>\n<li><em>Functional architects:</em> Detaillieren das Funktionsdesign (<code>Function design</code> – I/O-Definition, internes Verhalten, Subfunktionen; entspricht der VFB-Ebene / Virtual Function Bus).</li>\n<li><em>Electronic architects:</em> Führen das Funktions-ECU-Mapping durch (<code>Mapping of functions on ECU</code>) und erstellen das Kommunikationsnetzwerk (<code>Definition of comm matrix</code>, z. B. CAN/LIN/FlexRay-Cluster und Signal-PDU-Layouts).</li>\n<li><em>Schnittstellen-Artefakt:</em> <code>System Constraint Description</code> (ARXML-Austauschmodell mit Restriktionen bezüglich Busbandbreite, Latenzen, Topologie und Speicherbudget).</li>\n<li><strong>Organic domain (OEM + supplier):</strong></li>\n<li><em>Kollaborative Ebene:</em> Gemeinsame Konsolidierung der Systemspezifikation (<code>ECU system spec</code>).</li>\n<li><em>HW-Pfad:</em> Spezifikation (<code>HW spec</code>), getrieben durch die <code>ECU Resource Description</code> (Hardware-Eigenschaften: Controller-Architektur, RAM/ROM/Flash-Größen, Peripherie-Ports, Timings), überführt in die HW-Entwicklung (<code>HW dvpt</code>) bis zum finalen Target (<code>Hardware</code>).</li>\n<li><em>SW-Pfad:</em> Spezifikation (<code>SW spec</code>), formalisiert als <code>Software-component Description</code> (SWC-Template: Port-Interfaces, Internal Behavior, Runnables, Events), überführt in die SW-Implementierung (<code>SW dvpt</code>) bis zum generierten/implementierten Quellcode (<code>SWC code</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Prozess folgt einer strikten Kaskadierung mit paralleler Verzweigung in der Integrationsphase:</p>\n<ol class=\"fig-list\">\n<li><strong>Anforderungsdefinition (Car Domain):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>$T_0$: Erfassung der Kundenanforderungen (<code>Car features</code>).</li>\n<li>$T_1$: Formalisierung in funktionale Anforderungen (<code>Car functions</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Architektur & Allokation (Electronic Domain):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>$T_2$: VFB-konforme Schnittstellen- und Verhaltensdefinition (<code>Function design</code>).</li>\n<li>$T_3$: Synthese aus logischer Architektur und physischer Netzwerktopologie (<code>Mapping of functions on ECU</code> & <code>Definition of comm matrix</code>).</li>\n<li>$T_4$: Export der <code>System Constraint Description</code> als verbindliche Vorgabe an die Steuergeräteebene.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>ECU-Dekomposition & Implementierung (Organic Domain):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>$T_5$: Abstimmung der <code>ECU system spec</code> zwischen OEM und Tier-1.</li>\n<li>$T_6$: Verzweigung in parallele Spezifikations- und Entwicklungsstränge:</li>\n<li><strong>Hardware-Zweig:</strong> <code>HW spec</code> $\\rightarrow$ Parametrierung via <code>ECU Resource Description</code> $\\rightarrow$ Layout/Schaltungsentwicklung (<code>HW dvpt</code>) $\\rightarrow$ Fertigung/Lieferung (<code>Hardware</code>).</li>\n<li><strong>Software-Zweig:</strong> <code>SW spec</code> $\\rightarrow$ Generierung/Modellierung der <code>Software-component Description</code> $\\rightarrow$ Implementierung (<code>SW dvpt</code>) $\\rightarrow$ Kompilat/Source (<code>SWC code</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Entkopplung durch VFB:</strong> Bis zum Schritt <code>Mapping of functions on ECU</code> sind Applikationsfunktionen hardware-agnostisch modelliert. Entwickler implementieren Software-Komponenten (SWCs) ausschließlich gegen den durch die <code>Software-component Description</code> definierten API-Vertrag (Port-Interfaces, RTE-Contract-Phase).</li>\n<li><strong>Basis für RTE- und BSW-Generierung:</strong></li>\n<li>Die <code>Software-component Description</code> liefert das Input-Modell für den RTE-Generator zur Erzeugung von <code>Rte_&lt;swc&gt;.h</code> und des RTE-Glue-Codes.</li>\n<li>Die <code>ECU Resource Description</code> bildet die Basis für die MCAL- und BSW-Konfiguration (System Clocks, Memory Mapping, Pin-Multiplexing, ISR-Vektoren via Tresos, DaVinci Configurator o. ä.).</li>\n<li><strong>Lieferanten-Schnittstelle:</strong> Die strikte Trennung in <code>System Constraint Description</code>, <code>ECU Resource Description</code> und <code>Software-component Description</code> verhindert proprietäre Tool-Abhängigkeiten und sichert die Wiederverwendbarkeit von SWCs über verschiedene Hardware-Plattformen und Tier-1-Lieferanten hinweg.</li>\n</ul>"}], "trans": [{"from": "FIG-04ee44547ef6093f", "to": "FIG-3b33d83ce39c7c2c", "fr": "R2.1.20", "tr": "R3.0.7", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li><strong>Mapping of functions on ECU</strong> und <strong>Definition of comm matrix</strong>: Beide Textelemente sind nun in separaten weißen Rechteck-Boxen platziert (zuvor direkt auf dem blauen Trichterrumpf ohne Box).</li>\n<li><strong>Trichter-Geometrie (Polygon)</strong>: Die linke Konturlinie des sich nach unten verjüngenden Trichters weist nun stufenförmige Versätze/Einrückungen an den Bereichsgrenzen auf (oben bei <em>Car domain</em> sowie bei <em>Mapping of functions on ECU</em> und <em>Definition of comm matrix</em>).</li>\n</ul>"}]};
